-- Rollback-only fixtures in the new Supabase project. No real records or durable users.
BEGIN;
CREATE TEMP TABLE checks(label text, passed boolean);
GRANT INSERT ON checks TO authenticated, anon;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
SELECT set_config('request.jwt.claim.sub','',true);
RESET ROLE;
SELECT count(*) AS checks, count(*) FILTER (WHERE NOT passed) AS failures FROM checks;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM checks WHERE NOT passed) THEN RAISE EXCEPTION 'Steady isolation checks failed'; END IF; END $$;
ROLLBACK;
